test-case.test:
let $a := <a/>
let $b := $a transform with { insert node <b/> into . }
return (count($a/*), count($b/*), $a is $b)

declare function local:strip($e as element()) as element() {
  $e transform with { delete node @* }
};
local:strip(<a x="1" y="2"><b z="3"/></a>)

let $a := <a>1</a>
return (
  $a transform with { replace value of node . with 2 },
  $a
)

let $a := <a>{ for $i in 1 to 1000 return <b/> }</a>
let $c := $a transform with { delete node b[position() mod 2 = 0] }
return count($c/b)
